import os
import speech_recognition as sr
from google.cloud import speech

def stream_microphone(payload, config=None):
    config = config or {}

    client = speech.SpeechClient()

    # Configure the streaming request
    streaming_config = speech.StreamingRecognitionConfig(
        config=speech.RecognitionConfig(
            encoding=speech.RecognitionConfig.AudioEncoding.LINEAR16,
            sample_rate_hertz=16000,
            language_code=config.get("language_code", "en-US"),
        ),
        interim_results=True,
    )

    # A generator function to yield audio chunks from the microphone
    def audio_generator():
        r = sr.Recognizer()
        with sr.Microphone(sample_rate=16000) as source:
            while True:
                audio = r.listen(source, phrase_time_limit=5) # Listen for up to 5 seconds
                yield audio.frame_data

    # Create the streaming request
    requests = (
        speech.StreamingRecognizeRequest(audio_content=chunk)
        for chunk in audio_generator()
    )

    # Perform the streaming recognition and yield results
    responses = client.streaming_recognize(streaming_config, requests)

    def result_generator():
        for response in responses:
            if not response.results:
                continue

            result = response.results[0]
            if not result.alternatives:
                continue

            transcript = result.alternatives[0].transcript
            is_final = result.is_final

            yield {"text": transcript, "is_final": is_final}

    result = result_generator()
    return result
